  final String label;
  final String network;
  final bool isIntact;
  final double varianceRemovedPct;
  final Float32List rawZ;
  final Float32List cleanZ;
  final Float32List psdFreqs;
  final Float32List rawPsd;
  final Float32List cleanPsd;

  const RoiTraceDto({
    required this.roiIndex,
    required this.label,
    required this.network,
    required this.isIntact,
    required this.varianceRemovedPct,
    required this.rawZ,
    required this.cleanZ,
    required this.psdFreqs,
    required this.rawPsd,
    required this.cleanPsd,
  });

  @override
  int get hashCode =>
      roiIndex.hashCode ^
      label.hashCode ^
      network.hashCode ^
      isIntact.hashCode ^
      varianceRemovedPct.hashCode ^
      rawZ.hashCode ^
      cleanZ.hashCode ^
      psdFreqs.hashCode ^
      rawPsd.hashCode ^
      cleanPsd.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RoiTraceDto &&
          runtimeType == other.runtimeType &&
          roiIndex == other.roiIndex &&
          label == other.label &&
          network == other.network &&
          isIntact == other.isIntact &&
          varianceRemovedPct == other.varianceRemovedPct &&
          rawZ == other.rawZ &&
          cleanZ == other.cleanZ &&
          psdFreqs == other.psdFreqs &&
          rawPsd == other.rawPsd &&
          cleanPsd == other.cleanPsd;
}

class SliceRgba {
  final int width;
  final int height;
  final Uint8List rgba;
  final double minVal;
  final double maxVal;

  const SliceRgba({
    required this.width,
    required this.height,
    required this.rgba,
    required this.minVal,
    required this.maxVal,
  });

  @override
  int get hashCode =>
      width.hashCode ^
      height.hashCode ^
      rgba.hashCode ^
      minVal.hashCode ^
      maxVal.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SliceRgba &&
          runtimeType == other.runtimeType &&
          width == other.width &&
          height == other.height &&
          rgba == other.rgba &&
          minVal == other.minVal &&
          maxVal == other.maxVal;
}
